import sys
import math

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    r = int(math.isqrt(n))
    for i in range(3, r+1, 2):
        if n % i == 0:
            return False
    return True

def factorize(n):
    # returns list of (prime, exponent)
    res = []
    while n % 2 == 0:
        res.append(2)
        n //= 2
    i = 3
    while i*i <= n:
        while n % i == 0:
            res.append(i)
            n //= i
        i += 2
    if n > 1:
        res.append(n)
    return res

def is_400_number(n):
    if n < 36:
        return False
    facs = factorize(n)
    if len(facs) == 0:
        return False
    # count distinct primes and exponents
    primes = []
    counts = []
    for p in facs:
        if not primes or primes[-1] != p:
            primes.append(p)
            counts.append(1)
        else:
            counts[-1] += 1
    if len(primes) != 2:
        return False
    for c in counts:
        if c % 2 != 0:
            return False
    return True

def solve():
    import sys
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    Q = int(input_data[0])
    queries = [int(x) for x in input_data[1:1+Q]]
    # Precompute all 400 numbers up to 10^12
    # 400 number: N = p^(2a) * q^(2b) where p,q distinct primes, a,b >= 1
    # So N = (p^a)^2 * (q^b)^2 = (p^a * q^b)^2
    # So N is a perfect square of a number with exactly 2 distinct prime factors.
    # Let M = p^a * q^b, a,b >= 1. Then N = M^2.
    # We need to find all M such that M has exactly 2 distinct prime factors, and M^2 <= 10^12.
    # M <= 10^6.
    # So we need to find all integers M <= 10^6 with exactly 2 distinct prime factors.
    # Then N = M^2.
    # For each query A, find largest N <= A.
    # Since M <= 10^6, we can precompute all such M, sort them, compute N=M^2, sort N.
    # Then for each query, binary search.
    MAX_A = 10**12
    MAX_M = int(math.isqrt(MAX_A))  # 10^6
    # Sieve smallest prime factor up to MAX_M
    spf = list(range(MAX_M+1))
    for i in range(2, int(math.isqrt(MAX_M))+1):
        if spf[i] == i:
            for j in range(i*i, MAX_M+1, i):
                if spf[j] == j:
                    spf[j] = i
    # Find all M with exactly 2 distinct prime factors
    valid_M = []
    for m in range(2, MAX_M+1):
        # factorize using spf
        x = m
        primes = set()
        while x > 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        if len(primes) == 2:
            valid_M.append(m)
    # Compute N = M^2
    valid_N = [m*m for m in valid_M]
    valid_N.sort()
    # For each query, binary search
    import bisect
    out_lines = []
    for A in queries:
        idx = bisect.bisect_right(valid_N, A) - 1
        out_lines.append(str(valid_N[idx]))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def is_beautiful(n):
            s = 0
            p = 1
            while n > 0:
                d = n % 10
                s += d
                p *= d
                n //= 10
            return s != 0 and p % s == 0

        count = 0
        for num in range(l, r + 1):
            if is_beautiful(num):
                count += 1
        return count

from typing import List
from collections import defaultdict

class TrieNode:
    __slots__ = ('children', 'cnt')
    def __init__(self):
        self.children = {}
        self.cnt = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.cnt += 1
    def remove(self, word):
        node = self.root
        for ch in word:
            child = node.children[ch]
            child.cnt -= 1
            node = child
    def longest_prefix_with_min_count(self, k):
        node = self.root
        length = 0
        while True:
            found = False
            for ch, child in node.children.items():
                if child.cnt >= k:
                    length += 1
                    node = child
                    found = True
                    break
            if not found:
                break
        return length

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k > n - 1:
            return [0] * n
        trie = Trie()
        for w in words:
            trie.insert(w)
        ans = [0] * n
        for i, w in enumerate(words):
            trie.remove(w)
            if n - 1 < k:
                ans[i] = 0
            else:
                ans[i] = trie.longest_prefix_with_min_count(k)
            trie.insert(w)
        return ans

