sys.setrecursionlimit(1 << 25)

def majority(a, b, c):
    # returns 1 if at least two of a,b,c are 1, else 0
    return 1 if (a + b + c) >= 2 else 0

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    A = data[1].strip()
    L = len(A)
    # recursive DP on intervals
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(l, r):
        """returns (cost0, cost1) for substring A[l:r] (r exclusive)"""
        if r - l == 1:          # leaf
            if A[l] == '0':
                return (0, 1)   # already 0, need 1 change to become 1
            else:
                return (1, 0)   # already 1, need 1 change to become 0
        third = (r - l) // 3
        c0 = dp(l, l + third)
        c1 = dp(l + third, l + 2 * third)
        c2 = dp(l + 2 * third, r)
        cost0 = 10 ** 9
        cost1 = 10 ** 9
        # enumerate all 8 possibilities for (a,b,c)
        for a in (0, 1):
            da0, da1 = c0
            ca0 = da0 if a == 0 else da1
            for b in (0, 1):
                db0, db1 = c1
                cb0 = db0 if b == 0 else db1
                for c in (0, 1):
                    dc0, dc1 = c2
                    cc0 = dc0 if c == 0 else dc1
                    cur = ca0 + cb0 + cc0
                    if majority(a, b, c) == 0:
                        if cur < cost0:
                            cost0 = cur
                    else:
                        if cur < cost1:
                            cost1 = cur
        return (cost0, cost1)

    cost0_root, cost1_root = dp(0, L)

    # compute original final bit (by applying the operation)
    # we can reuse the recursion: the root's value is majority of its three children's values
    # which are already the original bits, so we compute it directly.
    def original_final(l, r):
        if r - l == 1:
            return int(A[l])
        third = (r - l) // 3
        v1 = original_final(l, l + third)
        v2 = original_final(l + third, l + 2 * third)
        v3 = original_final(l + 2 * third, r)
        return majority(v1, v2, v3)

    orig = original_final(0, L)
    desired = 1 - orig
    ans = cost0_root if desired == 0 else cost1_root
    print(ans)

