class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        def can(limit):
            # Check if we can make all runs of 0s and 1s have length <= limit using at most numOps flips
            # We process the string and for each maximal block, we need to break it into pieces of size <= limit
            # by flipping characters between pieces. 
            # For a block of length L of character c, to break into pieces of max size limit, we need ceil(L/limit) - 1 flips
            # because each flip can start a new piece.
            flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                L = j - i
                flips += (L + limit - 1) // limit - 1
                if flips > numOps:
                    return False
                i = j
            return flips <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

        # Buckets: for each value d <= threshold, store indices of nums that are multiples of d
        buckets = {}
        for i, v in enumerate(nums):
            if v > threshold:
                continue
            # Add v to all its proper divisor buckets
            for d in range(1, int(v**0.5) + 1):
                if v % d == 0:
                    if d <= threshold:
                        buckets.setdefault(d, []).append(i)
                    other = v // d
                    if other != d and other <= threshold:
                        buckets.setdefault(other, []).append(i)

        # For each bucket, union all indices in it
        for d, indices in buckets.items():
            for i in range(1, len(indices)):
                union(indices[0], indices[i])

        # Count components
        components = set()
        for i in range(n):
            components.add(find(i))

        return len(components)
